lable":"NO","column_default":"now()","ordinal_position":9},{"table_name":"sync_change_feed","column_name":"terminal_id","udt_schema":"pg_catalog","udt_name":"text","is_nullable":"YES","column_default":null,"ordinal_position":10}],"constraints":[{"name":"products_barcode_key","type":"u","table":"products","definition":"UNIQUE (barcode)"},{"name":"products_owner_store_id_fkey","type":"f","table":"products","definition":"FOREIGN KEY (owner_store_id) REFERENCES stores(id) ON DELETE SET NULL"},{"name":"products_pkey","type":"p","table":"products","definition":"PRIMARY KEY (id)"},{"name":"sales_bill_number_key","type":"u","table":"sales","definition":"UNIQUE (bill_number)"},{"name":"sales_member_id_fkey","type":"f","table":"sales","definition":"FOREIGN KEY (member_id) REFERENCES members(id)"},{"name":"sales_pkey","type":"p","table":"sales","definition":"PRIMARY KEY (id)"},{"name":"sale_items_pkey","type":"p","table":"sale_items","definition":"PRIMARY KEY (id)"},{"name":"sale_items_product_id_fkey","type":"f","table":"sale_items","definition":"FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL"},{"name":"sale_items_refunded_qty_bounds","type":"c","table":"sale_items","definition":"CHECK (((refunded_qty >= 0) AND (refunded_qty <= GREATEST(quantity, 0))))"},{"name":"sale_items_sale_id_fkey","type":"f","table":"sale_items","definition":"FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE"},{"name":"audit_logs_pkey","type":"p","table":"audit_logs","definition":"PRIMARY KEY (id)"},{"name":"stores_group_id_fkey","type":"f","table":"stores","definition":"FOREIGN KEY (group_id) REFERENCES store_groups(id) ON UPDATE CASCADE ON DELETE SET NULL"},{"name":"stores_location_type_check","type":"c","table":"stores","definition":"CHECK ((location_type = ANY (ARRAY['store'::text, 'main_building'::text, 'sub_warehouse'::text, 'central_warehouse'::text])))"},{"name":"stores_parent_id_fkey","type":"f","table":"stores","definition":"FOREIGN KEY (parent_id) REFERENCES stores(id) ON DELETE SET NULL"},{"name":"stores_pkey","type":"p","table":"stores","definition":"PRIMARY KEY (id)"},{"name":"sync_change_feed_operation_check","type":"c","table":"sync_change_feed","definition":"CHECK ((operation = ANY (ARRAY['insert'::text, 'update'::text, 'delete'::text])))"},{"name":"sync_change_feed_pkey","type":"p","table":"sync_change_feed","definition":"PRIMARY KEY (cursor)"},{"name":"change_history_action_check","type":"c","table":"change_history","definition":"CHECK ((action = ANY (ARRAY['insert'::text, 'update'::text, 'delete'::text])))"},{"name":"change_history_pkey","type":"p","table":"change_history","definition":"PRIMARY KEY (id)"}]}$metadata$;
 branch constant text := 'a611a328-2217-4d77-944a-5f6a637d123b';
 repair_key constant text := 'OWNERSHIP22-STR1-20261104';
 receipt_id constant uuid := md5('OWNERSHIP22-STR1-20261104')::uuid;
 before_rows jsonb; after_rows jsonb; receipt public.audit_logs%ROWTYPE;
 item jsonb; expected jsonb; actual jsonb; before_row jsonb; after_row jsonb;
 n integer; changed integer; feed_start bigint; replay boolean:=false; stamp timestamptz:=transaction_timestamp();
BEGIN
 IF current_user<>'postgres' OR current_database()<>'postgres' OR auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'OWNERSHIP22_WRONG_EXECUTION_IDENTITY';END IF;
 IF jsonb_array_length(manifest)<>22 OR (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(manifest))<>22 THEN RAISE EXCEPTION 'OWNERSHIP22_INVALID_MANIFEST';END IF;
 -- A single receipt serializes first execution and replay, including an absent row.
 IF NOT pg_try_advisory_xact_lock(hashtextextended(repair_key,0)) THEN RAISE EXCEPTION 'OWNERSHIP22_BUSY';END IF;
 PERFORM id FROM public.stores ORDER BY id FOR SHARE NOWAIT;
 IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id=branch AND code='STR1' AND group_id='361-degree-sports' AND is_active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'OWNERSHIP22_BRANCH_CHANGED';END IF;
 PERFORM p.id FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid ORDER BY p.id FOR UPDATE OF p NOWAIT;
 SELECT * INTO receipt FROM public.audit_logs WHERE id=receipt_id FOR UPDATE NOWAIT;
 replay:=FOUND;
 -- Run the same raw-source/ACL/schema/trigger guards before and after DML.
 FOR n IN 1..2 LOOP
  FOR expected IN SELECT value FROM jsonb_array_elements(metadata->'functions') LOOP
   SELECT jsonb_build_object('signature',expected->>'signature','body_md5',md5(p.prosrc),'owner',pg_get_userbyid(p.proowner),'acl',(SELECT jsonb_agg(x::text ORDER BY x::text) FROM unnest(p.proacl) x),'config',to_jsonb(p.proconfig),'strict',p.proisstrict,'definer',p.prosecdef,'volatility',p.provolatile) INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(expected->>'signature');
   IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP22_ROUTINE_CHANGED: %',expected->>'signature';END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(jsonb_build_object('table_name',c.relname,'tgname',t.tgname,'tgenabled',t.tgenabled,'trigger_definition',pg_get_triggerdef(t.oid),'signature',CASE WHEN ns.nspname='public' THEN 'public.' ELSE ns.nspname||'.' END||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')') ORDER BY c.relname,t.tgname),'[]') INTO actual FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE t.tgrelid IN ('public.products'::regclass,'public.audit_logs'::regclass,'public.change_history'::regclass,'public.sync_change_feed'::regclass) AND NOT t.tgisinternal;
  SELECT jsonb_agg(value ORDER BY value->>'table_name',value->>'tgname') INTO expected FROM jsonb_array_elements(metadata->'triggers');
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP22_TRIGGER_CHANGED';END IF;
  SELECT jsonb_agg(jsonb_build_object('table_name',table_name,'column_name',column_name,'udt_schema',udt_schema,'udt_name',udt_name,'is_nullable',is_nullable,'column_default',column_default,'ordinal_position',ordinal_position) ORDER BY table_name,ordinal_position) INTO actual FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('products','audit_logs','change_history','sync_change_feed','stores','sales','sale_items');
  SELECT jsonb_agg(value ORDER BY value->>'table_name',(value->>'ordinal_position')::integer) INTO expected FROM jsonb_array_elements(metadata->'columns');
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP22_SCHEMA_CHANGED';END IF;
  SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname) INTO actual FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid WHERE k.contype<>'n' AND k.conrelid IN ('public.products'::regclass,'public.audit_logs'::regclass,'public.change_history'::regclass,'public.sync_change_feed'::regclass,'public.stores'::regclass,'public.sales'::regclass,'public.sale_items'::regclass);
  SELECT jsonb_agg(value ORDER BY value->>'table',value->>'name') INTO expected FROM jsonb_array_elements(metadata->'constraints');
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP22_CONSTRAINT_CHANGED';END IF;
  IF n=2 THEN EXIT;END IF;
  SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_rows FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid;
  IF jsonb_array_length(after_rows) IS DISTINCT FROM 22 THEN RAISE EXCEPTION 'OWNERSHIP22_MISSING_PRODUCT';END IF;
  IF replay THEN
   IF receipt.action_category IS DISTINCT FROM 'maintenance' OR receipt.action_name IS DISTINCT FROM 'repair_product_ownership' OR receipt.target_module IS DISTINCT FROM 'inventory' OR receipt.action IS DISTINCT FROM 'repair' OR receipt.entity IS DISTINCT FROM 'products' OR receipt.details->>'execution_identity' IS DISTINCT FROM 'database maintenance / postgres' OR receipt.details->>'product_count' IS DISTINCT FROM '22' OR receipt.store_id IS DISTINCT FROM branch OR receipt.user_id IS NOT NULL OR receipt.user_name IS DISTINCT FROM current_user OR receipt.details->>'repair_key' IS DISTINCT FROM repair_key OR receipt.details->'manifest' IS DISTINCT FROM manifest OR receipt.after_state IS DISTINCT FROM after_rows OR jsonb_typeof(receipt.before_state) IS DISTINCT FROM 'array' OR jsonb_array_length(receipt.before_state)<>22 THEN RAISE EXCEPTION 'OWNERSHIP22_INVALID_REPLAY';END IF;
   before_rows:=receipt.before_state;
  ELSE
   before_rows:=after_rows;
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
   SELECT value INTO before_row FROM jsonb_array_elements(before_rows) WHERE value->>'id'=item->>'id';
   IF before_row IS NULL OR md5(before_row::text) IS DISTINCT FROM item->>'before_md5' OR before_row->'owner_store_id' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'OWNERSHIP22_BEFORE_IMAGE_CHANGED';END IF;
  END LOOP;
  -- Revalidate provenance instead of assigning products solely from stock state.
  IF EXISTS(SELECT 1 FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid WHERE p.stock_quantity IS DISTINCT FROM 0 OR p.stock_by_store IS DISTINCT FROM jsonb_build_object(branch,0) OR p.stock_by_store IS DISTINCT FROM public.canonical_stock_by_store(p.stock_by_store) OR p.catalogue_store_ids IS DISTINCT FROM public.received_product_catalogue_stores(p.id) OR p.deleted_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.sale_items i JOIN public.sales s ON s.id=i.sale_id WHERE i.product_id=p.id AND s.store_id=branch) OR EXISTS(SELECT 1 FROM public.sale_items i JOIN public.sales s ON s.id=i.sale_id WHERE i.product_id=p.id AND s.store_id IS DISTINCT FROM branch)) THEN RAISE EXCEPTION 'OWNERSHIP22_PROVENANCE_CHANGED';END IF;
  IF NOT replay THEN
   SELECT coalesce(max(cursor),0) INTO feed_start FROM public.sync_change_feed;
   PERFORM set_config('pos.source_application',repair_key,true);
   PERFORM set_config('pos.updated_by','',true);PERFORM set_config('pos.device_id','',true);PERFORM set_config('pos.sync_terminal','',true);
   UPDATE public.products p SET owner_store_id=branch FROM jsonb_array_elements(manifest) m WHERE p.id=(m->>'id')::uuid AND p.owner_store_id IS NULL;
   GET DIAGNOSTICS changed=ROW_COUNT;
   IF changed<>22 THEN RAISE EXCEPTION 'OWNERSHIP22_UPDATE_CARDINALITY';END IF;
   SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_rows FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid;
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
   SELECT value INTO before_row FROM jsonb_array_elements(before_rows) WHERE value->>'id'=item->>'id';
   SELECT value INTO after_row FROM jsonb_array_elements(after_rows) WHERE value->>'id'=item->>'id';
   IF after_row->>'owner_store_id' IS DISTINCT FROM branch OR (after_row-'owner_store_id'-'row_version'-'updated_at') IS DISTINCT FROM (before_row-'owner_store_id'-'row_version'-'updated_at') OR (after_row->>'row_version')::bigint IS DISTINCT FROM (before_row->>'row_version')::bigint+1 OR ((after_row->>'updated_at')::timestamptz IS DISTINCT FROM CASE WHEN replay THEN receipt.created_at ELSE stamp END) OR NOT public.product_available_in_catalogue((item->>'id')::uuid,branch) THEN RAISE EXCEPTION 'OWNERSHIP22_UNEXPECTED_PRODUCT_CHANGE';END IF;
   IF (SELECT count(*) FROM public.change_history h WHERE h.entity_type='products' AND h.entity_id=item->>'id' AND h.revision=(after_row->>'row_version')::bigint AND h.action='update' AND h.old_value=before_row-'stock_by_store'-'stock_quantity' AND h.new_value=after_row-'stock_by_store'-'stock_quantity' AND h.source_application=repair_key AND h.scope_type='BRANCH' AND h.scope_id=branch AND h.changed_by IS NULL AND h.device_id IS NULL AND h.terminal_id IS NULL)<>1 THEN RAISE EXCEPTION 'OWNERSHIP22_HISTORY_MISSING';END IF;
   IF (SELECT count(*) FROM public.sync_change_feed f WHERE f.organization_id='default' AND f.branch_id='global' AND f.terminal_id IS NULL AND f.table_name='products' AND f.entity_id=jsonb_build_object('id',item->>'id')::text AND f.operation='update' AND NOT f.tombstone AND f.row_version=(after_row->>'row_version')::bigint)<>1 THEN RAISE EXCEPTION 'OWNERSHIP22_PRODUCT_FEED_MISSING';END IF;
  END LOOP;
  IF NOT replay THEN
   INSERT INTO public.audit_logs(id,user_name,user_id,action_category,action_name,target_module,details,store_id,action,entity,before_state,after_state)
   VALUES(receipt_id,current_user,NULL,'maintenance','repair_product_ownership','inventory',jsonb_build_object('repair_key',repair_key,'manifest',manifest,'execution_identity','database maintenance / postgres','product_count',22),branch,'repair','products',before_rows,after_rows);
   IF (SELECT count(*) FROM public.sync_change_feed WHERE cursor>feed_start AND ((table_name='products' AND entity_id IN (SELECT jsonb_build_object('id',value->>'id')::text FROM jsonb_array_elements(manifest))) OR (table_name='audit_logs' AND entity_id=jsonb_build_object('id',receipt_id)::text)))<>23 THEN RAISE EXCEPTION 'OWNERSHIP22_FEED_CARDINALITY';END IF;
  END IF;
  IF (SELECT count(*) FROM public.sync_change_feed WHERE table_name='audit_logs' AND entity_id=jsonb_build_object('id',receipt_id)::text AND branch_id=branch AND terminal_id IS NULL AND operation='insert' AND NOT tombstone AND row_version=1)<>1 THEN RAISE EXCEPTION 'OWNERSHIP22_AUDIT_FEED_MISSING';END IF;
 END LOOP;
 RAISE NOTICE 'OWNERSHIP22 verified %, products22 / history22 / feed23 / receipt1',CASE WHEN replay THEN 'existing repair' ELSE 'new repair' END;
END;
$repair$;
COMMIT;
